Array FastVectorMath::compute_centroid_and_bounds(const PackedVector3Array &points) {
	Array result;
	if (points.size() == 0) {
		result.push_back(Vector3(0, 0, 0));
		result.push_back(Vector3(0, 0, 0));
		result.push_back(Vector3(0, 0, 0));
		return result;
	}

	Vector3 min_bounds = points[0];
	Vector3 max_bounds = points[0];
	Vector3 sum(0, 0, 0);

	for (int i = 0; i < points.size(); i++) {
		const Vector3 &p = points[i];
		if (p.x < min_bounds.x) min_bounds.x = p.x;
		if (p.y < min_bounds.y) min_bounds.y = p.y;
		if (p.z < min_bounds.z) min_bounds.z = p.z;
		if (p.x > max_bounds.x) max_bounds.x = p.x;
		if (p.y > max_bounds.y) max_bounds.y = p.y;
		if (p.z > max_bounds.z) max_bounds.z = p.z;
		sum += p;
	}

	double n = (double)points.size();
	Vector3 centroid((double)sum.x / n, (double)sum.y / n, (double)sum.z / n);

	result.push_back(centroid);
	result.push_back(min_bounds);
	result.push_back(max_bounds);
	return result;
}

float FastVectorMath::ray_sphere_intersection(const Vector3 &origin, const Vector3 &dir, const Vector3 &sphere_center, float radius) {
	Vector3 oc = origin - sphere_center;
	double a = (double)dir.dot(dir);
	double b = 2.0 * (double)oc.dot(dir);
	double c = (double)oc.dot(oc) - (double)radius * (double)radius;

	double discriminant = b * b - 4.0 * a * c;
	if (discriminant < 0.0) {
		return -1.0f;
	}

	double sq = Math::sqrt(discriminant);
	double t0 = (-b - sq) / (2.0 * a);
	double t1 = (-b + sq) / (2.0 * a);

	double t = t0;
	if (t < 0.0) {
		t = t1;
	}
	if (t < 0.0) {
		return -1.0f;
	}
	return (float)t;
}

